package com.dongqh.luckyhub.payment;import com.dongqh.luckyhub.payment.dto.*;import com.dongqh.luckyhub.payment.enums.PaymentResult;import com.dongqh.luckyhub.payment.service.PaymentService;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import java.util.*;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.assertThat;
@SpringBootTest class PaymentConcurrencyTests extends PaymentTestFixture { @Autowired PaymentService payments;@Test void tenDuplicateSuccessCallbacksConfirmOnce() throws Exception {createOrder("RACE-PAY-O");payments.create(userId,new CreatePaymentCommand("RACE-PAY","RACE-PAY-O"));String sig=payments.signForSimulation("RACE-PAY",PaymentResult.SUCCESS,9000L);var pool=Executors.newFixedThreadPool(10);var gate=new CountDownLatch(1);List<Future<?>> fs=new ArrayList<>();for(int i=0;i<10;i++)fs.add(pool.submit(()->{gate.await();return payments.callback(new PaymentCallbackCommand("RACE-PAY",PaymentResult.SUCCESS,null,sig));}));gate.countDown();for(var f:fs)f.get();pool.shutdown();assertThat(inventory.get(skuId,"MALL").consumedStock()).isOne();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM inventory_ledger WHERE business_no='CONFIRM:RACE-PAY-O'",Integer.class)).isOne();}}
